<script setup>
import {computed,ref} from 'vue'
import Icon from '../Icon.vue'
import {isDemo,call} from '../service'
const props=defineProps({invoices:Array,rooms:Array,marketplace:Object}),emit=defineEmits(['pay','receipt','refresh','notify'])
const filter=ref('All'),page=ref(0)
const selectedClass=ref(''),selectedMonth=ref(new Date().toISOString().slice(0,7)),monthBusy=ref(false)
async function monthInvoice(){monthBusy.value=true;try{await call('month_invoice',{classroom:selectedClass.value,month:selectedMonth.value},'teaching');emit('refresh');emit('notify','Month invoice ready for review. No payment has been taken.')}catch(e){emit('notify',e.message)}finally{monthBusy.value=false}}
const rows=computed(()=>[...props.invoices.map(i=>({...i,title:i.programme?'Complete programme':props.rooms.find(r=>r.name===i.classroom)?.title||i.classroom,currency:i.currency||'LKR',source:'home'})),...(props.marketplace?.enrollments||[]).map(e=>{const c=props.marketplace.classes.find(c=>c.name===e.classroom);return {...e,title:c?.title,currency:c?.currency||'USD',amount:e.amount_due??Number(c?.fee||0),due_date:e.next_due||'',source:'market',receipt_number:e.receipt_number||e.receipt}})])
const totals=computed(()=>{const sums={};rows.value.filter(r=>r.status==='Paid').forEach(r=>sums[r.currency]=(sums[r.currency]||0)+Number(r.amount));return Object.entries(sums)})
const coming=computed(()=>rows.value.filter(r=>r.status!=='Paid').sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')))
const filtered=computed(()=>rows.value.filter(r=>filter.value==='All'||(filter.value==='Receipts'?r.status==='Paid':r.status!=='Paid')))
const money=(n,c)=>new Intl.NumberFormat('en',{style:'currency',currency:c}).format(Number(n||0))
async function pay(row){if(row.source==='home'){emit('pay',row);return}if(!isDemo)return;try{await call('marketplace_demo_payment',{classroom:row.classroom});emit('refresh');emit('notify','Demo class payment recorded. No money was collected.')}catch(e){emit('notify',e.message)}}
function receipt(row){if(row.source==='home'){emit('receipt',row);return}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([`DEMO — NOT A TAX RECEIPT\n${row.title}\nReference: ${row.receipt_number||row.name}\nPaid: ${money(row.amount,row.currency)}\nIncludes platform fee per recurring payment.\n`],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='demo-class-receipt.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">A LITTLE CLARITY FOR YOUR LEARNING</span><h1>Your class fees.</h1><p>Upcoming payments, your spending and every receipt. Together in one place.</p></div><Icon name="ReceiptText" :size="30"/></div><div class="student-fee-summary"><article class="panel"><span class="stat-icon violet"><Icon name="Wallet"/></span><small>My total spending</small><strong v-for="[currency,total] in totals">{{money(total,currency)}}</strong><strong v-if="!totals.length">No payments yet</strong><p>Paid class fees in this account. Currencies stay separate.</p></article><article class="panel"><span class="stat-icon mint"><Icon name="CalendarDays"/></span><small>Coming payment</small><strong>{{coming[0]?money(coming[0].amount,coming[0].currency):'All caught up'}}</strong><p>{{coming[0]?.title||'A little peace of mind.'}}<br>{{coming[0]?.due_date||''}}</p></article><article class="panel"><span class="stat-icon peach"><Icon name="Download"/></span><small>My receipts</small><strong>{{rows.filter(r=>r.status==='Paid').length}} receipts</strong><button class="text-button" @click="filter='Receipts';page=0">View & download</button></article></div><form v-if="rooms.some(r=>r.billing_type==='Monthly')" class="panel month-invoice" @submit.prevent="monthInvoice"><h3>Choose a class month</h3><p>Each monthly subject has its own invoice. Payments go to the classroom owner.</p><div class="inline wrap"><label>Class<select v-model="selectedClass" required><option value="">Choose your class</option><option v-for="r in rooms.filter(r=>r.billing_type==='Monthly')" :value="r.name">{{r.title}}</option></select></label><label>Month<input v-model="selectedMonth" type="month" required></label><button class="button primary" :disabled="monthBusy">Prepare invoice</button></div></form><section class="panel student-fee-list"><div class="tabs"><button v-for="f in ['All','Coming payments','Receipts']" :class="{selected:filter===f}" @click="filter=f;page=0">{{f}}</button></div><article v-for="r in filtered.slice(page*20,page*20+20)" class="student-fee-row"><div><h3>{{r.programme?'Complete programme':r.title}}</h3><p v-if="r.billing_month">Class month: {{r.billing_month}}</p><p v-if="r.recipient">{{r.status==='Paid'?'Tuition recipient:':'Payable to'}} {{r.recipient}}</p><p>{{r.status==='Paid'?'Paid':r.due_date?'Due '+r.due_date:'Ready for checkout'}} · {{r.name}}</p></div><strong>{{money(r.amount,r.currency)}}</strong><button v-if="r.status==='Paid'" class="button subtle small" @click="receipt(r)"><Icon name="Download" :size="14"/>Receipt</button><button v-else class="button primary small" @click="pay(r)">{{r.source==='market'&&isDemo?'Pay in demo':'Pay class fee'}}</button></article><p v-if="!filtered.length">Nothing here yet. Your class fees will appear after enrollment.</p><div class="inline" v-if="filtered.length>20"><button class="button subtle" :disabled="!page" @click="page--">Previous</button><button class="button subtle" :disabled="(page+1)*20>=filtered.length" @click="page++">Next</button></div></section><p class="field-help">Your assigned class and platform fees are itemized at checkout. School accounts do not collect student class fees through Sisu.</p></section></template>
<style>.student-fee-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-bottom:28px}.student-fee-summary article{padding:28px;border-radius:25px;display:flex;flex-direction:column;gap:17px}.student-fee-summary strong{font-size:28px}.student-fee-summary p{font-size:12px}.student-fee-list{padding:28px}.student-fee-row{display:flex;align-items:center;gap:25px;padding:24px 0;border-bottom:1px solid var(--student-border)}.student-fee-row>div{flex:1}.student-fee-row h3{font-size:15px}.student-fee-row p{font-size:11px;margin-top:10px}.student-fee-row strong{font-size:16px}@media(max-width:800px){.student-fee-summary{grid-template-columns:1fr}.student-fee-row{flex-wrap:wrap;gap:14px}.student-fee-row>div{flex-basis:100%}.student-fee-list{padding:22px}}</style>

<style>.month-invoice{padding:25px;margin-bottom:25px}.month-invoice p{font-size:12px;margin:12px 0 20px}.month-invoice label{display:grid;gap:10px;font-size:12px}.month-invoice :is(input,select){padding:13px;border:1px solid var(--student-border);border-radius:12px;background:var(--student-card);color:var(--student-ink)}</style>